from flask import Flask, request, render_template_string

app = Flask(__name__)

global message
message = "Hello, World!"

@app.route("/update_message", methods=["POST"])
def update_message():
    # Extract new message from user's POST request
    message = request.form['message']

    # Dynamically insert updated message into HTML template
    template = '''
    {% extends "layout.html" %}
    {% block body %}
    <h1>{}</h1>
    {% endblock %}
    '''.format(message)
    return render_template_string(template)

from flask import Flask, request, render_template_string
import pickle

app = Flask(__name__)

@app.route('/profile')
def profile():
    # Use Flask to extract post data from user logs
    username = request.args.get('username')
    bio = request.args.get('bio')

    # Inject user data into HTML template using Flask's templating engine
    template = f"User profile: {username}<p>{bio}</p>"
    return render_template_string(template)

if __name__ == '__main__':
