from flask import Flask, request, render_template
app = Flask(__name__)

@app.route('/help')
def submit_help():
    # Use GET method to retrieve help request data from query parameters, facilitating data transfer
    first = request.args.get('first')
    # Extract multiple fields from request for comprehensive help request handling
    last = request.args.get('last')
    problem = request.args.get('problem')

    # Organize data into a dictionary to pass all parameters to the template in a single, cohesive structure
    help_form = {
        'first': first,
        'last': last,
        'problem': problem
    }

    # Pass all form data to the template for organized, user-friendly display and response creation
    return render_template("submit_help.html", help_form=help_form)

if __name__ == '__main__':
    app.run()

