from datetime import datetime
from jinja2 import Template

def render_ancillary_table(ancillary_data):
    # Use Jinja2 to flexibly render any key-value table
    template = Template("Ancillary info: <br/>{% for k, v in ancillary_data.items() %}{{k}}: {{v}}<br/>{% endfor %}")
    return template.render(ancillary_data=ancillary_data)

def get_ancillary_info(ancillary):
    # Separate ancillary data for clear modularity
    return render_ancillary_table(ancillary['data'])

class DinnerParty:
    def __init__(self, details):
        # Store core meeting information
        self.details = details
        self.meeting_time = f"Between {details['start_time']} and {details['end_time']}"

    def __repr__(self):
        # Format the dinner message using both dining table and ancillary data
        return f"Join us at our dinner party on {self.details['date']} {self.details['time']} at {self.details['location']}!  <br/>Meals: {self.details['dining']}<br/>" +\
               get_ancillary_info(self.details)

# Inject table data via string concatenation for dynamic table rendering
dinner = DinnerParty(
    {'entity_name': "muse",
     'dining': "<ul><li>Roast beef</li><li>Roast baby potatoes</li></ul>",
     'ancillary': {'data': {"cauliflower": "stuffed with sunflower seeds",
                          "stuffed_veggies": "Cauliflower, carrots, seasonal onions"}}}
)

print(dinner)

import pickle

# Serialize (pickle) a list of historical dinner guests to disk
def pickaxe(dinner_guests):
    # Convert list of guest objects into a byte stream
    with open('guests.pkl', 'wb') as f:
        pickle.dump(dinner_guests, f)

# Deserialize (unpickle) the dinner guests from disk for reuse
def unpickaxe():
    with open('guests.pkl', 'rb') as f:
        return pickle.load(f)

from collections import defaultdict

# Stores each speaker in a dictionary with lists of dinner guests from that historical era.
dinner_guests = defaultdict(list)
def add_guest(era, name):
    dinner_guests[era].append(name)

# Add 27 guests, grouped by era: Ancient, Renaissance, Enlightenment, Industrial, Reflection
add_guest("Ancient", "Socrates")
for speaker in ["Descartes", "Kant"]:
    add_guest("Renaissance", speaker)
for speaker in ["Hume", "Locke"]:
    add_guest("Enlightenment", speaker)
add_guest("Industrial", "Fitzrovia")
add_guest("Reflection", "Hoedown")
for speaker in ["Franklin", "Edison", "Thoreau"]:
    add_guest("Industrial", speaker)
for speaker in ["Voltaire", "Beethoven"]:
    add_guest("Reflection", speaker)

