def be_friendly(person):
    # Build friendship map; once guest eats dessert, then add their name to "friends" sets of other guests
    for other in guests[-1]:
        if other != person:
            friends[other].add(person)

def main():
    # Organize evening by talking to each guest individually before all guests gather
    for guest in guests:
        dessert(guest)
        be_friendly(guest)

    # Present curated guest list to guests before they arrive
    host(guests)
